<?php declare(strict_types=1);namespace App\Modules\Subcontracts\Services;use App\Core\Database\Database;use App\Core\Exceptions\BusinessRuleException;use App\Modules\Subcontracts\DTOs\SubcontractData;use App\Modules\Subcontracts\Repositories\SubcontractRepository;use App\Shared\Numbering\NumberGeneratorService;final class SubcontractService{private const T=['draft'=>['active','cancelled'],'active'=>['suspended','completed','cancelled'],'suspended'=>['active','completed','cancelled'],'completed'=>[],'cancelled'=>[]];public function __construct(private readonly SubcontractRepository$r,private readonly NumberGeneratorService$n,private readonly Database$db){}public function find(int$id):array{return$this->r->find($id)??throw new BusinessRuleException('عقد مقاول الباطن غير موجود.');}public function refs():array{return$this->r->refs();}public function all():array{return$this->r->all();}public function save(SubcontractData$d,?int$id=null):int{$old=$id?$this->find($id):null;if(!$this->r->project($d->projectId))throw new BusinessRuleException('المشروع غير موجود.');$switch=$old===null||(int)$old['vendor_id']!==$d->vendorId;if(!$this->r->vendor($d->vendorId,$switch))throw new BusinessRuleException('يجب اختيار مقاول باطن نشط.');if($d->number!==null&&$this->r->numberExists($d,$id))throw new BusinessRuleException('رقم العقد مستخدم لهذا المشروع والمقاول.');return$this->db->transaction(function()use($d,$id,$old){if(!$id)return$this->r->create($this->n->nextSubcontractCode((int)substr($d->contractDate,0,4)),$d);$boq=$this->r->boq($id);if($boq&&$boq['status']==='approved'&&($d->pricingMethod!==$old['pricing_method']||$d->value!==(string)$old['contract_value']))throw new BusinessRuleException('القيمة وطريقة التسعير محميتان بـ BOQ معتمد.');if($old['status']!=='draft')$this->locked($old,$d);$this->r->update($id,$d,$old['status']==='draft');return$id;});}public function change(int$id,string$s):void{$x=$this->find($id);if(!in_array($s,self::T[$x['status']]??[],true))throw new BusinessRuleException('انتقال الحالة غير مسموح.');if($s==='active'){$b=$this->r->boq($id);if($x['pricing_method']==='boq'&&(!$b||$b['status']!=='approved'))throw new BusinessRuleException('يجب اعتماد BOQ قبل التفعيل.');if($b&&$b['status']!=='approved')throw new BusinessRuleException('اعتمد أو احذف النطاق الاختياري أولًا.');}$this->r->status($id,$s);}public function transitions(string$s):array{return self::T[$s]??[];}private function locked(array$o,SubcontractData$d):void{foreach(['project_id'=>$d->projectId,'vendor_id'=>$d->vendorId,'pricing_method'=>$d->pricingMethod,'subcontract_number'=>$d->number,'contract_value'=>$d->value,'contract_date'=>$d->contractDate,'title'=>$d->title,'description'=>$d->description]as$k=>$v)if(($o[$k]===null?null:(string)$o[$k])!==($v===null?null:(string)$v))throw new BusinessRuleException('لا يمكن تعديل البيانات التعاقدية بعد التفعيل.');}}
